<?php
$pdfStatusLabels = ['brouillon'=>'Brouillon', 'a_controler'=>'Contrôle Trésorier A', 'soumise'=>'Validation comptable', 'validee_comptable'=>'Validation Direction', 'validee_direction'=>'Approuvée', 'en_suspens'=>'En suspens', 'ordre_emis'=>'Ordre émis', 'payee'=>'Payée', 'annulee'=>'Annulée', 'rejetee'=>'Rejetée'];
$pdfLevelLabels = ['tresorier'=>'Trésorier A', 'comptable'=>'Comptable senior', 'direction_financiere'=>'Direction financière', 'direction_generale'=>'Direction générale'];
$pdfDecisionLabels = ['valide'=>'Validé', 'en_suspens'=>'En suspens', 'annule'=>'Annulé', 'repris'=>'Repris', 'rejete'=>'Rejeté'];
$pdfAccountant = '';
$pdfDirection = '';
foreach (($validations ?? []) as $validation) {
    if (($validation['decision'] ?? '') !== 'valide') continue;
    if ($validation['approval_level'] === 'comptable') $pdfAccountant = $validation['approved_by_nom'] ?? '';
    if (in_array($validation['approval_level'], ['direction_financiere', 'direction_generale'], true)) $pdfDirection = $validation['approved_by_nom'] ?? '';
}
$pdfApproved = (float)($demande['approved_amount'] ?? $demande['amount']);
?>
<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><style>
@page{margin:35px 36px 42px}body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#203650;line-height:1.5}h1{font-size:20px;line-height:1.25;margin:0;color:#183b60}h2{font-size:10px;color:#234d76;margin:18px 0 8px}.eyebrow{font-size:7px;text-transform:uppercase;letter-spacing:1px;color:#8091a3}.header{width:100%;border-collapse:collapse;border-bottom:3px solid #264e78;margin-bottom:16px}.header td{padding-bottom:15px;vertical-align:top}.right{text-align:right}.number{font-size:11px;font-weight:bold;margin-top:6px}.status{font-size:8px;color:#5f7892}.info{width:100%;border-collapse:collapse}.info td{padding:10px 12px;border:1px solid #dce4ed;vertical-align:top;width:50%}.label{font-size:7px;color:#7c8d9f;text-transform:uppercase}.value{font-size:10px;font-weight:bold}.items{border-collapse:collapse;width:100%;margin-top:7px}.items th{padding:9px 8px;background:#edf3f9;border:1px solid #d6e1ec;text-align:left;font-size:7px;color:#3b5d7e}.items td{padding:9px 8px;border:1px solid #dce4ed;vertical-align:top}.items .right{text-align:right;white-space:nowrap}.total td{font-weight:bold;background:#f4f8fc}.justification{border:1px solid #dce4ed;padding:12px;min-height:65px;word-wrap:break-word}.note{font-size:7px;color:#8190a0}.approved{padding:10px 12px;background:#eef6f1;border-left:3px solid #599679;margin-top:10px}.signatures{width:100%;border-collapse:collapse;table-layout:fixed;page-break-inside:avoid}.signatures td{width:33.33%;border:1px solid #dce4ed;padding:11px;vertical-align:top}.signature-title{font-weight:bold;font-size:8px;min-height:27px}.signature-name{font-size:8px;height:28px}.signature-space{height:52px;border-bottom:1px dotted #9eb0c3;margin-bottom:7px}.journal{border-collapse:collapse;width:100%;font-size:7px}.journal td,.journal th{padding:7px 6px;border-bottom:1px solid #e2e8ef;text-align:left;vertical-align:top}.journal th{background:#f2f6fa;color:#627990}.footer{position:fixed;bottom:-25px;left:0;right:0;border-top:1px solid #dce4ed;padding-top:7px;font-size:6px;color:#8291a2}.cancel{background:#fff0f1;color:#a53541;padding:10px;margin:12px 0}.wrap{word-wrap:break-word}
</style></head><body>
<table class="header"><tr><td><div class="eyebrow"><?= e(APP_NAME) ?> · Trésorerie</div><h1>Fiche de demande<br>d’achat / fonds</h1></td><td class="right"><div class="eyebrow">Numéro de la demande</div><div class="number"><?= e($demande['request_number']) ?></div><div class="status"><?= e($pdfStatusLabels[$demande['status']] ?? $demande['status']) ?></div></td></tr></table>
<?php if ($demande['status'] === 'annulee'): ?><div class="cancel"><strong>DEMANDE ANNULÉE — ARCHIVE</strong><br><?= nl2br(e($demande['cancellation_reason'] ?? '')) ?></div><?php endif; ?>
<h2>1. Informations générales</h2><table class="info"><tr><td><div class="label">Département demandeur</div><div class="value"><?= e($demande['department'] ?? '—') ?></div></td><td><div class="label">Nom du demandeur</div><div class="value"><?= e($demande['requester_name'] ?? $demande['created_by_nom'] ?? '—') ?></div></td></tr><tr><td><div class="label">Date</div><div class="value"><?= formatDate($demande['request_date']) ?></div></td><td><div class="label">Bénéficiaire</div><div class="value"><?= e($demande['beneficiary']) ?></div></td></tr><tr><td colspan="2"><div class="label">Objet</div><div class="value"><?= e($demande['objet']) ?></div></td></tr></table>
<h2>2. Détail des biens et services</h2><div class="note">Devise : <?= e($demande['currency']) ?> · Prix estimatifs unitaires</div><table class="items"><thead><tr><th style="width:5%">N°</th><th>Services / Biens</th><th class="right" style="width:11%">Quantité</th><th class="right" style="width:20%">Prix unitaire estimé</th><th class="right" style="width:20%">Montant total</th></tr></thead><tbody><?php foreach (($lignesDemande ?? []) as $index => $line): ?><tr><td><?= $index + 1 ?></td><td class="wrap"><?= e($line['description']) ?></td><td class="right"><?= e(rtrim(rtrim(number_format((float)$line['quantity'], 4, '.', ' '), '0'), '.')) ?></td><td class="right"><?= formatMontant((float)$line['unit_price'], $demande['currency']) ?></td><td class="right"><?= formatMontant((float)($line['line_total'] ?? (float)$line['quantity'] * (float)$line['unit_price']), $demande['currency']) ?></td></tr><?php endforeach; ?><?php if (empty($lignesDemande)): ?><tr><td colspan="5" class="note">Demande historique : détail disponible dans la justification.</td></tr><?php endif; ?></tbody><tfoot><tr class="total"><td colspan="4" class="right">Total demandé</td><td class="right"><?= formatMontant((float)$demande['amount'], $demande['currency']) ?></td></tr></tfoot></table>
<?php if ($demande['currency'] === 'CDF'): ?><div class="note" style="margin-top:7px">Taux appliqué : 1 USD = <?= formatMontant((float)($demande['exchange_rate'] ?? 0), 'CDF') ?> · Contre-valeur : <?= formatMontant((float)$demande['amount_usd'], 'USD') ?></div><?php endif; ?>
<?php if ($pdfApproved < (float)$demande['amount']): ?><div class="approved"><strong>Validation partielle : <?= formatMontant($pdfApproved, $demande['currency']) ?> autorisés</strong><br>Solde non autorisé : <?= formatMontant((float)$demande['amount'] - $pdfApproved, $demande['currency']) ?>. Ce solde ne peut pas être payé sur cette demande.</div><?php endif; ?>
<h2>3. Justification du besoin</h2><div class="justification"><?= nl2br(e($demande['description'] ?? '')) ?></div>
<h2>4. Validation</h2><table class="signatures"><tr><td><div class="signature-title">Chef de département</div><div class="signature-name">Nom : ____________________</div><div class="signature-space"></div><div class="note">Signature manuscrite</div><div>Date : ____ / ____ / ______</div></td><td><div class="signature-title">Service comptable / finance</div><div class="signature-name"><?= e($pdfAccountant ?: 'Nom : ____________________') ?></div><div class="signature-space"></div><div class="note">Signature manuscrite</div><div>Date : ____ / ____ / ______</div></td><td><div class="signature-title">Direction</div><div class="signature-name"><?= e($pdfDirection ?: 'Nom : ____________________') ?></div><div class="signature-space"></div><div class="note">Signature manuscrite</div><div>Date : ____ / ____ / ______</div></td></tr></table><p class="note">Les noms issus du circuit identifient les intervenants ; les signatures manuscrites sont recueillies sur l’exemplaire imprimé.</p>
<?php if (!empty($validations)): ?><h2>Journal des décisions</h2><table class="journal"><thead><tr><th>Date</th><th>Niveau / Intervenant</th><th>Décision</th><th>Observation</th></tr></thead><tbody><?php foreach ($validations as $validation): ?><tr><td><?= !empty($validation['approved_at']) ? e(date('d/m/Y H:i', strtotime($validation['approved_at']))) : '—' ?></td><td><?= e($pdfLevelLabels[$validation['approval_level']] ?? $validation['approval_level']) ?><br><?= e($validation['approved_by_nom'] ?? '') ?></td><td><?= e($pdfDecisionLabels[$validation['decision']] ?? $validation['decision']) ?><?php if (isset($validation['approved_amount'])): ?><br><?= formatMontant((float)$validation['approved_amount'], $demande['currency']) ?><?php endif; ?><?php if (!empty($validation['reminder_date'])): ?><br>Rappel : <?= formatDate($validation['reminder_date']) ?><?php endif; ?></td><td class="wrap"><?= nl2br(e($validation['approval_comment'] ?? '')) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
<div class="footer"><?= e(APP_NAME) ?> · <?= e($demande['request_number']) ?> · Généré le <?= date('d/m/Y à H:i') ?> par <?= e($_SESSION['user_nom'] ?? 'Utilisateur autorisé') ?></div>
</body></html>
